type DateSegment = DateSegmentProps['segment'];

export type DateTimeInputProps = {
  children: ReactNode;
};

export const DateTimeInput = ({ children }: DateTimeInputProps) => {
  const { id, required, onBlur, onFocus, FieldLayout } =
    useFieldPropsV2<DateTimeFieldProps>();

  const { inputId, labelId, ariaDescribedBy } = useFieldAttributes();
  const { regionalFormat } = useConfig();

  const dateFormat = useMemo(
    () =>
      getDateFormatParts(regionalFormat)
        .filter(isSupportedDatePart)
        .map((part) => part.toUpperCase() as SupportedDateParts),
    [regionalFormat],
  );

  const labelElement = findChildOfType(children, DateTimeInput.Label);
  const descriptionElement = findChildOfType(
    children,
    DateTimeInput.Description,
  );
  const errorElement = findChildOfType(children, DateTimeInput.Error);

  const dateElementsByPart = {
    [SupportedDateParts.MONTH]: findChildOfType(children, DateTimeInput.Month),
    [SupportedDateParts.DAY]: findChildOfType(children, DateTimeInput.Day),
    [SupportedDateParts.YEAR]: findChildOfType(children, DateTimeInput.Year),
  };

  const timeElement = findChildOfType(children, DateTimeInput.Time);

  return (
    <FieldLayout
      fieldId={id}
      renderLabel={() =>
        applyInternalProps<LabelInternalProps>(labelElement, { as: 'div' })
      }
      renderInput={() => (
        <FieldsetHeadless
          id={inputId}
          ariaLabelledBy={labelId}
          ariaDescribedBy={ariaDescribedBy}
          required={required}
          onBlur={onBlur}
          onFocus={onFocus}
        >
          {dateElementsByPart[dateFormat[0]]}
          {dateElementsByPart[dateFormat[1]]}
          {dateElementsByPart[dateFormat[2]]}
          {timeElement}
        </FieldsetHeadless>
      )}
      renderDescription={() => (
        <>
          {descriptionElement}
          {errorElement}
        </>
      )}
    />
  );
};

type MonthProps = {
  children: ReactNode;
  className?: string;
};

const Month = ({ children, className }: MonthProps) => {
  const { id, disabled, showDateLabels } =
    useFieldPropsV2<DateTimeFieldProps>();
  const { inputId } = useDateTimeFieldAttributes(SupportedDateParts.MONTH);
  const { partValue, partError, onPartChange, isFirstPart } = useFieldPart(
    SupportedDateParts.MONTH,
  );
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMonthChange = useCallback(
    (selectedValue: React.Key | null) => {
      onPartChange(typeof selectedValue === 'string' ? selectedValue : '');
    },
    [onPartChange],
  );

  useFocusFieldEvent(() => {
    if (isFirstPart) {
      buttonRef.current?.focus();
    }
  }, id);

  const labelElement = findChildOfType(children, Month.Label);
  const optionsElement = findChildOfType(children, Month.Options);

  return (
    <div className={className} data-date-field={true}>
      {showDateLabels ? labelElement : null}
      <SelectRAC
        value={partValue || null}
        onChange={handleMonthChange}
        isDisabled={disabled}
        isInvalid={partError}
      >
        <ButtonRAC
          ref={buttonRef}
          id={inputId}
          data-hook={SupportedDateParts.MONTH}
          data-invalid={partError}
        >
          <SelectValueRAC />
        </ButtonRAC>
        {optionsElement}
      </SelectRAC>
    </div>
  );
};

type MonthLabelProps = {
  className?: string;
};

const MonthLabel = ({ className }: MonthLabelProps) => {
  return (
    <DateTimeLabel datePart={SupportedDateParts.MONTH} className={className} />
  );
};

type MonthOptionsProps = {
  children: ReactNode;
  className?: string;
};

const MonthOptions = ({ children, className }: MonthOptionsProps) => {
  const { locale } = useConfig();

  const months = useMemo(() => getMonthList(locale), [locale]);

  const optionElement = findChildOfType(children, MonthOptions.Option) ?? (
    <MonthOptions.Option />
  );

  return (
    <PopoverRAC className={className}>
      <ListBoxRAC>
        {months.map((month, index) =>
          applyInternalProps<MonthOptionInternalProps>(optionElement, {
            key: String(index + 1),
            value: String(index + 1),
            label: month,
          }),
        )}
      </ListBoxRAC>
    </PopoverRAC>
  );
};

type MonthOptionProps = {
  className?: string;
};

type MonthOptionInternalProps = {
  value: string;
  label: string;
};

const MonthOption = ({ className, ...internal }: MonthOptionProps) => {
  const { value, label } = internal as MonthOptionInternalProps;
  return (
    <ListBoxItemRAC className={className} id={value} textValue={label}>
      {label}
    </ListBoxItemRAC>
  );
};

Month.Label = MonthLabel;
Month.Options = MonthOptions;
MonthOptions.Option = MonthOption;

