type TimeLabelProps = {
  className?: string;
};

const TimeLabel = ({ className }: TimeLabelProps) => {
  const { inputId, labelId } = useDateTimeFieldAttributes('time');
  const { t } = useTranslation();

  const label = t('field.date.label.time');

  return (
    <label id={labelId} htmlFor={inputId} className={className}>
      {label}
    </label>
  );
};

type TimeInputProps = {
  children: ReactNode;
  className?: string;
};

const TimeInput = ({ children, className }: TimeInputProps) => {
  const hourElement = findChildOfType(children, Time.Hour);
  const minuteElement = findChildOfType(children, Time.Minute);
  const periodElement = findChildOfType(children, Time.Period);

  return (
    <DateInputRAC className={className}>
      {(segment) => {
        switch (segment.type) {
          case 'hour':
            return (
              applyInternalProps<HourInternalProps>(hourElement, {
                segment,
              }) || <></>
            );
          case 'minute':
            return (
              applyInternalProps<MinuteInternalProps>(minuteElement, {
                segment,
              }) || <></>
            );
          case 'dayPeriod':
            return (
              applyInternalProps<PeriodInternalProps>(periodElement, {
                segment,
              }) || <></>
            );
          case 'literal':
            return <DateSegmentRAC segment={segment} />;
          default:
            return <></>;
        }
      }}
    </DateInputRAC>
  );
};

