function useDateTimeFieldAttributes(datePart: SupportedDateParts | 'time') {
  const { inputId } = useFieldAttributes();

  return useMemo(() => {
    const partName = datePart.toLowerCase();
    return {
      inputId: `${inputId}-${partName}-input`,
      labelId: `${inputId}-${partName}-label`,
    };
  }, [inputId, datePart]);
}

function useFieldPart(part: 'time'): {
  partValue: TimeValue | null;
  partError: boolean;
  onPartChange: (newValue: TimeValue | null) => void;
  isFirstPart: boolean;
};
function useFieldPart(part: SupportedDateParts): {
  partValue: string;
  partError: boolean;
  onPartChange: (newValue: string) => void;
  isFirstPart: boolean;
};
function useFieldPart(part: SupportedDateParts | 'time') {
  const {
    value: fieldValue,
    onChange: fieldOnChange,
    hasError = false,
  } = useFieldPropsV2<DateTimeFieldProps>();
  const { regionalFormat } = useConfig();

  const [dateValue, timeValue] = useMemo(
    () => parseDateTimeValue(fieldValue ?? ''),
    [fieldValue],
  );
  const errors = useMemo(
    () => getDateTimePartsErrors(hasError, fieldValue ?? ''),
    [fieldValue, hasError],
  );

  const dateValues = useMemo(() => deserializeDate(dateValue), [dateValue]);
  const parsedTimeValue = useMemo(
    () => stringToTimeValue(timeValue),
    [timeValue],
  );

  const onTimeChange = useCallback(
    (newValue: TimeValue | null) => {
      const stringValue = timeValueToString(newValue);
      const serializedValue = formatDateTimeValue(dateValue, stringValue);
      fieldOnChange(serializedValue);
    },
    [fieldOnChange, dateValue],
  );

  const onPartChange = useCallback(
    (newValue: string) => {
      const [, currentTime] = parseDateTimeValue(fieldValue ?? '');
      const serializedDate = serializeDate(
        newValue,
        part as SupportedDateParts,
        dateValues,
      );
      const serializedValue = formatDateTimeValue(serializedDate, currentTime);
      fieldOnChange(serializedValue);
    },
    [fieldOnChange, fieldValue, dateValues, part],
  );

  const isFirstPart = useMemo(() => {
    if (part === 'time') {
      return false;
    }
    const dateFormat = getDateFormatParts(regionalFormat)
      .filter(isSupportedDatePart)
      .map((p) => p.toUpperCase() as SupportedDateParts);
    const firstPart = dateFormat[0];
    return firstPart === part;
  }, [regionalFormat, part]);

  if (part === 'time') {
    return {
      partValue: parsedTimeValue,
      partError: errors.TIME,
      onPartChange: onTimeChange,
      isFirstPart: false,
    };
  }

  const partValue = dateValues[part] || '';

  return {
    partValue,
    partError: errors[part],
    onPartChange,
    isFirstPart,
  };
}

type DateTimeLabelProps = {
  datePart: SupportedDateParts;
  className?: string;
};

function DateTimeLabel({ datePart, className }: DateTimeLabelProps) {
  const { inputId, labelId } = useDateTimeFieldAttributes(datePart);
  const { t } = useTranslation();

  const translationKey = `field.date.label.${datePart.toLowerCase()}`;
  const label = t(translationKey);

  return (
    <label id={labelId} htmlFor={inputId} className={className}>
      {label}
    </label>
  );
}

function stringToTimeValue(value: string | null | undefined): TimeValue | null {
  if (!value) {
    return null;
  }
  try {
    return parseTime(value);
  } catch {
    return null;
  }
}

function timeValueToString(time: TimeValue | null): string | null {
  if (!time) {
    return null;
  }
  const hour = String(time.hour).padStart(2, '0');
  const minute = String(time.minute).padStart(2, '0');
  const second = String(time.second).padStart(2, '0');

  return [hour, minute, second].join(':');
}
