export function formatCurrency({
  amount = 0,
  currency,
  locale,
  decimalCount,
}: {
  amount?: number | string;
  currency?: string;
  locale?: string;
  decimalCount?: number;
} = {}): string {
  const amountNumber = Number(amount);

  if (currency) {
    return Intl.NumberFormat(locale, {
      style: 'currency',
      unitDisplay: 'narrow',
      currency,
      minimumFractionDigits: decimalCount,
      maximumFractionDigits: decimalCount ?? getPrecision(amountNumber),
    }).format(amountNumber);
  }

  if (decimalCount) {
    return amountNumber.toFixed(decimalCount);
  }

  return String(amount);
}

function getPrecision(amount: number): number {
  return amount.toString().split('.')[1]?.length || 0;
}
