import { type WixFile } from '../../form/types';
import { writeTextOnCanvas } from './text';
import {
  createCanvas,
  createCanvasFromDataUrl,
  getCroppedCanvas,
  getScaledCanvas,
} from './canvas';
import { MAX_HEIGHT } from './constants';
import { SignatureFormat } from '../signature-types';
import { decodePoints } from './points';
import SignaturePad from 'signature_pad';

const DATA_URI_REGEX = /^data:([^;,]+)(?:;([^,]+))?,(.+)$/;

export function isDataUrl(dataUrl: string): dataUrl is `data:${string}` {
  return DATA_URI_REGEX.test(dataUrl);
}

export interface DataURL {
  data: string;
  mimeType: SignatureFormat.POINTS | SignatureFormat.TEXT | string;
  encoding?: 'text' | 'base64';
}

export function decodeDataUrl(dataUrl: string): DataURL | undefined {
  if (!dataUrl) {
    return undefined;
  }

  const match = dataUrl.match(DATA_URI_REGEX);
  if (!match) {
    return undefined;
  }

  const [, mimeType, encoding, data] = match;
  return {
    data: encoding === 'base64' ? atob(data) : decodeURI(data),
    mimeType,
    encoding: encoding as DataURL['encoding'],
  };
}

export function encodeDataUrl({
  data,
  mimeType,
  encoding = 'text',
}: DataURL): string {
  const encodedData = encoding === 'base64' ? btoa(data) : encodeURI(data);
  const typeAndEncoding =
    encoding === 'base64' ? `${mimeType};base64` : mimeType;
  return `data:${typeAndEncoding},${encodedData}`;
}

export function dataUrlToFile(
  dataUrl: string,
  filename: string,
): File | undefined {
  const decoded = decodeDataUrl(dataUrl);
  if (!decoded) {
    return undefined;
  }

  let n = decoded.data.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = decoded.data.charCodeAt(n);
  }

  const extension = decoded.mimeType.split('/')[1] ?? 'txt';
  return new File([u8arr], `${filename}.${extension}`, {
    type: decoded.mimeType,
  });
}

export function dataUrlToWixFile(url: string, displayName = 'temp'): WixFile {
  const decoded = decodeDataUrl(url);
  return {
    fileId: 'temp',
    displayName,
    url,
    fileType: decoded?.mimeType ?? '',
  };
}

export async function dataUrlToPngDataUrl(
  dataUrl: string,
  rtl?: boolean,
): Promise<string | null> {
  const decodedDataUrl = decodeDataUrl(dataUrl);
  if (!decodedDataUrl) {
    return dataUrl;
  }
  const dataUrlType = decodedDataUrl.mimeType;
  if (dataUrlType === SignatureFormat.TEXT) {
    // Width doesn't matter, it will be cropped later
    const canvas = createCanvas(MAX_HEIGHT * 20, MAX_HEIGHT, 1);
    writeTextOnCanvas(canvas, decodedDataUrl.data, 'black', rtl, 'white');
    const croppedCanvas = getCroppedCanvas(canvas, 'white');
    // When cropped canvas is null it means we have an empty image ( example a transparent background )
    return croppedCanvas?.toDataURL('image/jpeg', 0.7) ?? null;
  }
  if (dataUrlType === SignatureFormat.POINTS) {
    const points = decodePoints(dataUrl);
    if (!points) {
      return null;
    }
    const blackPoints = points.map((pointGroup) => ({
      ...pointGroup,
      penColor: 'black',
    }));
    // Width doesn't matter, it will be cropped later
    const canvas = createCanvas(
      MAX_HEIGHT * 20,
      MAX_HEIGHT,
      Math.max(window.devicePixelRatio || 1, 1),
    );
    const signaturePad = new SignaturePad(canvas);
    signaturePad.fromData(blackPoints);
    const croppedCanvas = getCroppedCanvas(canvas);
    if (!croppedCanvas) {
      // Empty image case
      return null;
    }
    const scaledCanvas = getScaledCanvas(
      croppedCanvas,
      undefined,
      MAX_HEIGHT,
      'white',
    );
    return scaledCanvas.toDataURL('image/jpeg', 0.7);
  }
  if (dataUrlType?.startsWith('image/')) {
    const canvas = await createCanvasFromDataUrl(dataUrl);
    const croppedCanvas = getCroppedCanvas(canvas);
    if (!croppedCanvas) {
      // Empty image case
      return null;
    }
    const scaledCanvas = getScaledCanvas(croppedCanvas, undefined, MAX_HEIGHT);
    return scaledCanvas.toDataURL('image/jpeg', 0.7);
  }
  return dataUrl;
}

export async function convertToPNGFile(
  dataUrl: string,
  rtl?: boolean,
): Promise<File | undefined> {
  const pngDataUrl = await dataUrlToPngDataUrl(dataUrl, rtl);
  if (!pngDataUrl) {
    return undefined;
  }
  return dataUrlToFile(pngDataUrl, 'signature');
}
