  [ErrorTypes.TYPE_ERROR]: 'input.error.message.type-error',
  [ErrorTypes.REQUIRED_VALUE_ERROR]: 'input.error.message.required-error',
  [ErrorTypes.UNKNOWN_VALUE_ERROR]: 'input.error.message.unknown-value-error',
  [ErrorTypes.MAX_LENGTH_ERROR]: 'input.error.message.max-length-error',
  [ErrorTypes.MIN_LENGTH_ERROR]: 'input.error.message.min-length-error',
  [ErrorTypes.PATTERN_ERROR]: 'input.error.message.pattern-error',
  [ErrorTypes.FORMAT_ERROR]: 'input.error.message.format-error',
  [ErrorTypes.MAX_VALUE_ERROR]: 'input.error.message.max-value-error',
  [ErrorTypes.MIN_VALUE_ERROR]: 'input.error.message.min-value-error',
  [ErrorTypes.MULTIPLE_OF_VALUE_ERROR]:
    'input.error.message.multiple-of-value-error',
  [ErrorTypes.MIN_ITEMS_ERROR]: 'input.error.message.min-items-error',
  [ErrorTypes.MAX_ITEMS_ERROR]: 'input.error.message.max-items-error',
  [ErrorTypes.NOT_ALLOWED_VALUE_ERROR]: 'input.error.message.not-allowed-value',
  [ErrorTypes.FIELDS_COMPATIBILITY_ERROR]:
    'input.error.fields-compatibility-error',
  [ErrorTypes.FIELDS_COUNT_RESTRICTIONS_ERROR]:
    'input.error.fields-count-restrictions-error',
  [ErrorTypes.FORMS_COUNT_RESTRICTIONS_ERROR]:
    'input.error.forms-count-restrictions-error',
  [ErrorTypes.STEPS_COUNT_RESTRICTIONS_ERROR]:
    'input.error.steps-count-restrictions-error',
  [ErrorTypes.RULES_COUNT_RESTRICTIONS_ERROR]:
    'input.error.rules-count-restrictions-error',
  [ErrorTypes.FILE_UPLOAD_RESTRICTIONS_ERROR]:
    'input.error.file-upload-restrictions-error',
  [ErrorTypes.DISABLED_FORM_ERROR]: 'input.error.disabled-form-error',
  [ErrorTypes.INVALID_PHONE_COUNTRY_CODE_ERROR]:
    'input.error.message.invalid-phone-country-code-error',
  [ErrorTypes.INVALID_STAFF_ID_ERROR]:
    'input.error.message.invalid-staff-id-error',
  [ErrorTypes.INVALID_LOCATION_ID_ERROR]:
    'input.error.message.invalid-location-id-error',
  [ErrorTypes.MISSING_SERVICE_OPTION_ERROR]: 'TBD',
  [ErrorTypes.INVALID_SERVICE_OPTIONS_ERROR]: 'TBD',
  [ErrorTypes.NO_AVAILABLE_SERVICE_OPTIONS_ERROR]: 'TBD',
