  [ErrorTypes.CHARACTER_LENGTH_RANGE_ERROR]:
    'input.error.message.character-length-range-error',
  [ErrorTypes.VALUE_RANGE_ERROR]: 'input.error.message.value-range-error',
  [ErrorTypes.EXACT_ITEMS_NUMBER_ERROR]:
    'input.error.message.exact-items-number-error',
  [ErrorTypes.DECIMAL_POINT_ERROR]: 'input.error.message.decimal_point_error',
  [ErrorTypes.INCOMPLETE_DATE_ERROR]:
    'input.error.message.incomplete-date-error',
  [ErrorTypes.INVALID_VALUE_FOR_PATTERN_ERROR]:
    'input.error.message.invalid-value-for-pattern',
