import { type FieldType } from '../constants';
import {
  CALLING_COUNTRY_CODES,
  type ValidationError,
} from '@wix/form-validator';
import {
  type PublicDonationProps,
  type PublicAppointmentProps,
  type PublicImageChoiceProps,
  type PublicProductListProps,
  type PublicFixedPaymentProps,
  type PublicPaymentInputProps,
  type PublicSubmitButtonProps,
  type PublicRichTextProps,
  type PublicTimeInputProps,
  type PublicRadioGroupProps,
  type PublicCheckboxGroupProps,
  type PublicDropdownProps,
  type PublicTagsProps,
  type PublicCheckboxProps,
  type PublicSignatureProps,
  type PublicRatingInputProps,
  type PublicNumberInputProps,
  type PublicDateTimeInputProps,
  type PublicDateInputProps,
  type PublicDatePickerProps,
  type PublicFileUploadProps,
  type PublicMultilineAddressProps,
  type PublicPhoneInputProps,
  type PublicTextInputProps,
  type PublicTextAreaProps,
  type PublicFieldsProps,
} from '../types/public-props';

const allCallingCountryCodes = Object.keys(CALLING_COUNTRY_CODES);

// TODO: strongly type all params
const MinMaxLengthMapper = (validation: any) => ({
  maxLength: validation?.string?.maxLength,
  minLength: validation?.string?.minLength,
});

const MinMaxItemsMapper = (validation: any) => ({
  minItems: validation?.array?.minItems,
  maxItems: validation?.array?.maxItems,
});

const MinMaxValuesMapper = (validation: any) => {
  return {
    minValue:
      validation?.predefined?.paymentOptions?.products?.[0]?.dynamicPriceOptions
        .minPrice,
    maxValue:
      validation?.predefined?.paymentOptions?.products?.[0]?.dynamicPriceOptions
        .maxPrice,
  };
};

const AcceptedDatesMapper = (validation: any) => ({
  acceptedDates:
    validation?.string?.dateOptions?.minimum === '$now'
      ? 'future'
      : validation?.string?.dateOptions?.maximum === '$now'
      ? 'past'
      : 'all',
});

const CustomOptionMapper = (props: any) => {
  const { addOther, addOtherLabel, addOtherPlaceholder } = props;
  return {
    customOption: addOther
      ? {
          label: addOtherLabel,
          placeholder: addOtherPlaceholder,
        }
      : undefined,
  };
};

// Convert ValidationError to error message string
const ErrorMapper = (
  error: ValidationError | undefined,
): string | undefined => {
  if (!error) {
    return undefined;
  }
  return error.errorMessage || 'Validation error';
};

const BaseMapper = (props: any) => {
  const { hideLabel, error, showLabel, ...rest } = props;

  return {
    ...rest,
    showLabel: hideLabel === undefined ? true : !hideLabel,
    error: ErrorMapper(error),
  };
};

const TextFieldMapper = (props: any): PublicTextInputProps => ({
  ...props,
  ...MinMaxLengthMapper(props?.validation),
  ...BaseMapper(props),
});

const TextAreaMapper = (props: any): PublicTextAreaProps => ({
  ...props,
  ...MinMaxLengthMapper(props?.validation),
  ...BaseMapper(props),
});

const PhoneInputMapper = (props: any): PublicPhoneInputProps => {
  const { defaultCountry, defaultCountryCode, validation } = props;
  const allowedCountryCodes =
    validation?.string?.phoneOptions?.allowedCountryCodes;

  return {
    ...props,
    ...BaseMapper(props),
    defaultCountryCode: defaultCountry ?? defaultCountryCode,
    countryCodes:
      allowedCountryCodes && allowedCountryCodes.length > 0
        ? allowedCountryCodes
        : allCallingCountryCodes,
  };
};

const MultilineAddressMapper = (props: any): PublicMultilineAddressProps => {
  const { view, validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    showAddressLine2: view?.fieldSettings?.addressLine2?.show,
    addressLine2Required:
      validation?.predefined?.multilineAddressOptions?.fields?.addressLine2
        ?.required,
  };
};

const DateInputMapper = (props: any): PublicDateInputProps => {
  const { hidePlaceholder, validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    ...AcceptedDatesMapper(validation),
    showPlaceholder: hidePlaceholder === undefined ? true : !hidePlaceholder,
  };
};

const DatePickerMapper = (props: any): PublicDatePickerProps => {
  const { validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    ...AcceptedDatesMapper(validation),
  };
};

const DateTimeInputMapper = (props: any): PublicDateTimeInputProps => {
  const { hidePlaceholder, validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    ...AcceptedDatesMapper(validation),
    showPlaceholder: hidePlaceholder === undefined ? true : !hidePlaceholder,
  };
};

const FileUploadMapper = (props: any): PublicFileUploadProps => {
  const { valueSliderLimit, uploadFileFormats } = props;
  return {
    ...props,
    ...BaseMapper(props),
    maxFiles: valueSliderLimit,
    allowedFileFormats: uploadFileFormats,
  };
};

const NumberInputMapper = (props: any): PublicNumberInputProps =>
  BaseMapper(props);

const CheckboxMapper = (props: any): PublicCheckboxProps => {
  const { error, ...rest } = props;
  return {
    ...rest,
    error: ErrorMapper(error),
  };
};

const SignatureMapper = (props: any): PublicSignatureProps => {
  const { uploadEnabled } = props;
  return {
    ...props,
    ...BaseMapper(props),
    imageUploadEnabled: uploadEnabled,
  };
};

const RatingInputMapper = (props: any): PublicRatingInputProps =>
  BaseMapper(props);

const RadioGroupMapper = (props: any): PublicRadioGroupProps => {
  return {
    ...props,
    ...BaseMapper(props),
    ...CustomOptionMapper(props),
  };
};

const CheckboxGroupMapper = (props: any): PublicCheckboxGroupProps => {
  const { validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    ...CustomOptionMapper(props),
    ...MinMaxItemsMapper(validation),
  };
};

const DropdownMapper = (props: any): PublicDropdownProps => BaseMapper(props);

const TagsMapper = (props: any): PublicTagsProps => {
  const { validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    ...CustomOptionMapper(props),
    ...MinMaxItemsMapper(validation),
  };
};

const TimeInputMapper = (props: any): PublicTimeInputProps => {
  const { hidePlaceholder } = props;
  return {
    ...props,
    ...BaseMapper(props),
    showPlaceholder: hidePlaceholder === undefined ? true : !hidePlaceholder,
  };
};

const TextMapper = (props: any): PublicRichTextProps => props;

const SubmitButtonMapper = (props: any): PublicSubmitButtonProps => {
  return {
    ...props,
  };
};

const ProductListMapper = (props: any): PublicProductListProps => {
  return {
    ...props,
    ...BaseMapper(props),
    ...MinMaxItemsMapper(props?.validation),
  };
};

const FixedPaymentMapper = (props: any): PublicFixedPaymentProps => {
  const { validation, hideLabel, showLabel, ...rest } = props;
  const paymentValidation =
    validation?.predefined?.paymentOptions?.products?.[0];
  const fixedPaymentValue = paymentValidation?.fixedPriceOptions?.price;

  return {
    ...rest,
    validation,
    showLabel: hideLabel === undefined ? true : !hideLabel,
    amount: fixedPaymentValue,
  };
};

const PaymentInputMapper = (props: any): PublicPaymentInputProps => {
  const { validation } = props;
  return {
    ...props,
    ...BaseMapper(props),
    ...MinMaxValuesMapper(validation),
  };
};

const DonationMapper = (props: any): PublicDonationProps => {
  return {
    ...props,
    ...BaseMapper(props),
    ...CustomOptionMapper(props),
  };
};

const AppointmentMapper = (props: any): PublicAppointmentProps =>
  BaseMapper(props);

const ImageChoiceMapper = (props: any): PublicImageChoiceProps => {
  const { isMultipleAnswers, choiceImageResize } = props;
  return {
    ...props,
    ...BaseMapper(props),
    multiple: isMultipleAnswers,
    imageAspectRatio: choiceImageResize,
  };
};

const DefaultMapper = (props: any) => {
  const { error, ...rest } = props;
  return {
    ...rest,
    error: ErrorMapper(error),
  };
};

export { BaseMapper };

