export interface LayoutData_BackgroundImage {
  /** Background image. */
  media?: Media;
  /** Background image opacity. */
  opacity?: number;
  /** Background image scaling. */
  scaling: LayoutData_ImageScaling_Scaling;
  /** Position of background. Defaults to `CENTER`. */
  position: LayoutData_ImagePosition;
}

const baseLayoutData: object = {
  cellPadding: 0,
  cellVerticalAlignment: LayoutData_VerticalAlignment_Alignment.TOP,
  responsivenessBehaviour: LayoutData_ResponsivenessBehaviour.STACK,
};

export const LayoutData = {
  fromJSON(object: any): LayoutData {
    const message = { ...baseLayoutData } as LayoutData;
    message.backgroundColor =
      object.backgroundColor !== undefined && object.backgroundColor !== null
        ? String(object.backgroundColor)
        : undefined;
    message.backgroundImage =
      object.backgroundImage !== undefined && object.backgroundImage !== null
        ? LayoutData_BackgroundImage.fromJSON(object.backgroundImage)
        : undefined;
    message.borderColor =
      object.borderColor !== undefined && object.borderColor !== null
        ? String(object.borderColor)
        : undefined;
    message.borderWidth =
      object.borderWidth !== undefined && object.borderWidth !== null
        ? Number(object.borderWidth)
        : undefined;
    message.borderRadius =
      object.borderRadius !== undefined && object.borderRadius !== null
        ? Number(object.borderRadius)
        : undefined;
    message.backdropColor =
      object.backdropColor !== undefined && object.backdropColor !== null
        ? String(object.backdropColor)
        : undefined;
    message.backdropImage =
      object.backdropImage !== undefined && object.backdropImage !== null
        ? LayoutData_BackgroundImage.fromJSON(object.backdropImage)
        : undefined;
    message.backdropPaddingTop =
      object.backdropPaddingTop !== undefined && object.backdropPaddingTop !== null
        ? Number(object.backdropPaddingTop)
        : undefined;
    message.backdropPaddingBottom =
      object.backdropPaddingBottom !== undefined && object.backdropPaddingBottom !== null
        ? Number(object.backdropPaddingBottom)
        : undefined;
    message.gap = object.gap !== undefined && object.gap !== null ? Number(object.gap) : undefined;
    message.cellPadding = (object.cellPadding ?? []).map((e: any) => Number(e));
    message.cellVerticalAlignment =
      object.cellVerticalAlignment !== undefined && object.cellVerticalAlignment !== null
        ? layoutData_VerticalAlignment_AlignmentFromJSON(object.cellVerticalAlignment)
        : LayoutData_VerticalAlignment_Alignment.TOP;
    message.responsivenessBehaviour =
      object.responsivenessBehaviour !== undefined && object.responsivenessBehaviour !== null
        ? layoutData_ResponsivenessBehaviourFromJSON(object.responsivenessBehaviour)
        : LayoutData_ResponsivenessBehaviour.STACK;
    message.responsivenessBreakpoint =
      object.responsivenessBreakpoint !== undefined && object.responsivenessBreakpoint !== null
        ? Number(object.responsivenessBreakpoint)
        : undefined;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    return message;
  },

  toJSON(message: LayoutData): unknown {
    const obj: any = {};
    message.backgroundColor !== undefined && (obj.backgroundColor = message.backgroundColor);
    message.backgroundImage !== undefined &&
      (obj.backgroundImage = message.backgroundImage
        ? LayoutData_BackgroundImage.toJSON(message.backgroundImage)
        : undefined);
    message.borderColor !== undefined && (obj.borderColor = message.borderColor);
    message.borderWidth !== undefined && (obj.borderWidth = message.borderWidth);
    message.borderRadius !== undefined && (obj.borderRadius = message.borderRadius);
    message.backdropColor !== undefined && (obj.backdropColor = message.backdropColor);
    message.backdropImage !== undefined &&
      (obj.backdropImage = message.backdropImage
        ? LayoutData_BackgroundImage.toJSON(message.backdropImage)
        : undefined);
    message.backdropPaddingTop !== undefined &&
      (obj.backdropPaddingTop = message.backdropPaddingTop);
    message.backdropPaddingBottom !== undefined &&
      (obj.backdropPaddingBottom = message.backdropPaddingBottom);
    message.gap !== undefined && (obj.gap = message.gap);
    if (message.cellPadding) {
      obj.cellPadding = message.cellPadding.map(e => Math.round(e));
    } else {
      obj.cellPadding = [];
    }
    message.cellVerticalAlignment !== undefined &&
      (obj.cellVerticalAlignment = layoutData_VerticalAlignment_AlignmentToJSON(
        message.cellVerticalAlignment
      ));
    message.responsivenessBehaviour !== undefined &&
      (obj.responsivenessBehaviour = layoutData_ResponsivenessBehaviourToJSON(
        message.responsivenessBehaviour
      ));
    message.responsivenessBreakpoint !== undefined &&
      (obj.responsivenessBreakpoint = message.responsivenessBreakpoint);
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    return obj;
  },
};

const baseLayoutData_VerticalAlignment: object = {};

export const LayoutData_VerticalAlignment = {
  fromJSON(_: any): LayoutData_VerticalAlignment {
    const message = { ...baseLayoutData_VerticalAlignment } as LayoutData_VerticalAlignment;
    return message;
  },

  toJSON(_: LayoutData_VerticalAlignment): unknown {
    const obj: any = {};
    return obj;
  },
};

const baseLayoutData_ImageScaling: object = {};

export const LayoutData_ImageScaling = {
  fromJSON(_: any): LayoutData_ImageScaling {
    const message = { ...baseLayoutData_ImageScaling } as LayoutData_ImageScaling;
    return message;
  },

  toJSON(_: LayoutData_ImageScaling): unknown {
    const obj: any = {};
    return obj;
  },
};

const baseLayoutData_BackgroundImage: object = {
  scaling: LayoutData_ImageScaling_Scaling.AUTO,
  position: LayoutData_ImagePosition.CENTER,
};

export const LayoutData_BackgroundImage = {
  fromJSON(object: any): LayoutData_BackgroundImage {
    const message = { ...baseLayoutData_BackgroundImage } as LayoutData_BackgroundImage;
    message.media =
      object.media !== undefined && object.media !== null
        ? Media.fromJSON(object.media)
        : undefined;
    message.opacity =
      object.opacity !== undefined && object.opacity !== null ? Number(object.opacity) : undefined;
    message.scaling =
      object.scaling !== undefined && object.scaling !== null
        ? layoutData_ImageScaling_ScalingFromJSON(object.scaling)
        : LayoutData_ImageScaling_Scaling.AUTO;
    message.position =
      object.position !== undefined && object.position !== null
        ? layoutData_ImagePositionFromJSON(object.position)
        : LayoutData_ImagePosition.CENTER;
    return message;
  },

  toJSON(message: LayoutData_BackgroundImage): unknown {
    const obj: any = {};
    message.media !== undefined &&
      (obj.media = message.media ? Media.toJSON(message.media) : undefined);
    message.opacity !== undefined && (obj.opacity = message.opacity);
    message.scaling !== undefined &&
      (obj.scaling = layoutData_ImageScaling_ScalingToJSON(message.scaling));
    message.position !== undefined &&
      (obj.position = layoutData_ImagePositionToJSON(message.position));
    return obj;
  },
};
