export function makeViewOfInputField(
  inputOptions: InputField | PlatformizedInputField,
): object {
  switch (inputOptions.inputType) {
    case InputType.STRING:
      return resolveStringComponent(inputOptions.stringOptions!);
    case InputType.NUMBER:
      return resolveNumberComponent(inputOptions.numberOptions!);
    case InputType.BOOLEAN:
      return resolveBooleanComponent(inputOptions.booleanOptions!);
    case InputType.ARRAY:
      return resolveArrayComponent(inputOptions.arrayOptions!);
    case InputType.PAYMENT:
      return resolvePaymentComponent(inputOptions.paymentOptions!);
    case InputType.WIX_FILE:
      return resolveWixFileComponent(inputOptions.wixFileOptions!);
    case InputType.ADDRESS:
      return resolveMultilineAddressComponent(inputOptions.addressOptions!);
    case InputType.MULTILINE_ADDRESS:
      return resolveMultilineAddressComponent(
        inputOptions.multilineAddressOptions!,
      );
    case InputType.SCHEDULING:
      return resolveSchedulingComponent(inputOptions.schedulingOptions!);
    case InputType.OBJECT_ARRAY:
      return resolveObjectArrayComponent(inputOptions.objectArrayOptions!);
    default:
      throw new Error(`Unknown input type ${inputOptions.inputType}`);
  }
}

function resolveWixFileComponent(wixFileComponent: WixFile): object {
  switch (wixFileComponent.componentType) {
    case WixFileComponentType.FILE_UPLOAD:
      return takeWixFileInputViewProperties(
        wixFileComponent.fileUploadOptions!,
        wixFileComponent.validation!,
      );
    case WixFileComponentType.SIGNATURE:
      return takeSignatureInputViewProperties(
        wixFileComponent.signatureOptions!,
      );
    default:
      throw new Error(
        `Unknown wix file component type: ${wixFileComponent.componentType}`,
      );
  }
}

function takeWixFileInputViewProperties(
  fileUpload: FileUpload,
  validation: FileType,
): object {
  const fileFormats = (validation.uploadFileFormats ?? []).map(
    (format: string) => {
      switch (format) {
        case UploadFileFormat.VIDEO:
          return 'Video';
        case UploadFileFormat.IMAGE:
          return 'Image';
        case UploadFileFormat.AUDIO:
          return 'Audio';
        case UploadFileFormat.DOCUMENT:
          return 'Document';
        case UploadFileFormat.ARCHIVE:
          return 'Archive';
        default:
          throw new Error(`Unknown file format: ${format}`);
      }
    },
  );

  return {
    [HideLabelKey]: !fileUpload.showLabel,
    [UploadFileFormatsKey]: fileFormats,
    [ValueSliderLimitKey]: validation.fileLimit,
    ...(fileUpload.description && { [DescriptionKey]: fileUpload.description }),
    ...(fileUpload.label && { [LabelKey]: fileUpload.label }),
    ...(fileUpload.buttonText && { [ButtonTextKey]: fileUpload.buttonText }),
    ...(fileUpload.explanationText && {
      [ExplanationTextKey]: fileUpload.explanationText,
    }),
  };
}

function takeSignatureInputViewProperties(signature: Signature): object {
  return {
    [UploadEnabledKey]: signature.imageUploadEnabled,
    [HideLabelKey]: !signature.showLabel,
    ...(signature.label && { [LabelKey]: signature.label }),
    ...(signature.description && { [DescriptionKey]: signature.description }),
  };
}

function resolveArrayComponent(arrayComponent: _Array): object {
  const quizSettings = resolveQuizFieldSettings(
    arrayComponent.quizFieldSettings,
  );
  switch (arrayComponent.componentType) {
    case ComponentType.CHECKBOX_GROUP:
      return {
        ...takeCheckboxGroupViewProperties(
          arrayComponent.checkboxGroupOptions!,
        ),
        ...quizSettings,
      };
    case ComponentType.SERVICES_CHECKBOX_GROUP:
      return {
        ...takeCheckboxGroupViewProperties(
          arrayComponent.servicesCheckboxGroupOptions!,
        ),
        ...quizSettings,
      };
    case ComponentType.TAGS:
      return {
        ...takeTagsViewProperties(arrayComponent.tagsOptions!),
        ...quizSettings,
      };
    default:
      throw new Error(
        `Unknown array component type: ${arrayComponent.componentType}`,
      );
  }
}

function takeCheckboxGroupViewProperties(checkboxGroup: CheckboxGroup): object {
  return {
    [HideLabelKey]: !checkboxGroup.showLabel,
    [AddOtherKey]: checkboxGroup.customOption != null,
    [OptionsKey]: checkboxGroup.options!.map((option: any) =>
      makeOptionView(option),
    ),
    [NumberOfColumnsKey]: numericNumberOfColumns(
      checkboxGroup.numberOfColumns ?? NumberOfColumns.ONE,
    ),
    [DefaultValueKey]: checkboxGroup
      .options!.filter((option: any) => option.default)
      .map((option: any) => option.value),
    ...(checkboxGroup.description && {
      [DescriptionKey]: checkboxGroup.description,
    }),
    ...(checkboxGroup.label && { [LabelKey]: checkboxGroup.label }),
    ...(checkboxGroup.customOption && {
      [AddOtherLabelKey]: checkboxGroup.customOption.label,
      [AddOtherPlaceholderKey]: checkboxGroup.customOption.placeholder,
    }),
  };
}

