function makeOptionView(option: any): Record<string, any> {
  return {
    [LabelKey]: option.label,
    [ValueKey]: option.value,
    [idKey]: option.id,
    ...(option.media && { [MediaKey]: option.media }),
  };
}

function numericNumberOfColumns(numberOfColumnsEnum: string): number {
  switch (numberOfColumnsEnum) {
    case 'ZERO':
      return 0;
    case 'TWO':
      return 2;
    case 'THREE':
      return 3;
    default:
      return 1;
  }
}

function resolveObjectArrayComponent(
  objectArrayComponent: ObjectArray,
): object {
  switch (objectArrayComponent.componentType) {
    case ObjectArrayComponentType.REPEATER:
      return takeRepeaterViewProperties(objectArrayComponent.repeaterOptions!);
    default:
      throw new Error(
        `Unknown object array component type: ${objectArrayComponent.componentType}`,
      );
  }
}

function takeRepeaterViewProperties(repeater: Repeater): object {
  return {
    [LabelKey]: repeater.label,
    [HideLabelKey]: !repeater.showLabel,
    [RepeaterFieldsKey]: repeater.fields?.map(transformFieldToV1),
    [RepeaterLayoutKey]: repeater.layout,
    ...(repeater.description && { [DescriptionKey]: repeater.description }),
  };
}

function resolveQuizFieldSettings(quizFieldSettings?: {
  score?: number;
  correctAnswersList?: { correctAnswers?: any[] };
}): object {
  const correctAnswers = quizFieldSettings?.correctAnswersList?.correctAnswers;
  return {
    ...(quizFieldSettings?.score !== undefined && {
      [ScoreKey]: quizFieldSettings.score,
    }),
    ...(correctAnswers?.length && { [CorrectAnswersKey]: correctAnswers }),
  };
}
