const Day = ({ children, className }: DayProps) => {
  const { disabled, showDateLabels } = useFieldPropsV2<DateInputProps>();
  const { partValue, partError, onPartChange } = useDatePart(
    SupportedDateParts.DAY,
  );

  const labelElement = findChildOfType(children, Day.Label);
  const inputElement = findChildOfType(children, Day.Input);

  return (
    <div className={className} data-date-field={true}>
      {showDateLabels && labelElement}
      <TextFieldRAC
        value={partValue}
        onChange={onPartChange}
        isDisabled={disabled}
        isInvalid={partError}
      >
        {inputElement}
      </TextFieldRAC>
    </div>
  );
};

type DayLabelProps = {
  className?: string;
};

const DayLabel = ({ className }: DayLabelProps) => {
  return <DateLabel datePart={SupportedDateParts.DAY} className={className} />;
};

type DayInputProps = {
  className?: string;
};

const DayInput = ({ className }: DayInputProps) => {
  const { id, hidePlaceholder } = useFieldPropsV2<DateInputProps>();
  const { inputId } = useDateFieldAttributes(SupportedDateParts.DAY);
  const { isFirstPart } = useDatePart(SupportedDateParts.DAY);
  const { t } = useTranslation();
  const inputRef = useRef<HTMLInputElement>(null);

  const placeholder = hidePlaceholder
    ? undefined
    : t('field.date.placeholder.day');

  useFocusFieldEvent(() => {
    if (isFirstPart) {
      inputRef.current?.focus();
    }
  }, id);

  return (
    <InputRAC
      ref={inputRef}
      id={inputId}
      className={className}
      placeholder={placeholder}
      maxLength={2}
      inputMode="numeric"
      data-hook={SupportedDateParts.DAY}
    />
  );
};

Day.Label = DayLabel;
Day.Input = DayInput;

