DateInput.Label = Label;
DateInput.Month = Month;
DateInput.Day = Day;
DateInput.Year = Year;
DateInput.Description = Description;
DateInput.Error = Error;

function useDateFieldAttributes(datePart: SupportedDateParts) {
  const { inputId } = useFieldAttributes();

  return useMemo(() => {
    const partName = datePart.toLowerCase();
    return {
      inputId: `${inputId}-${partName}-input`,
      labelId: `${inputId}-${partName}-label`,
    };
  }, [inputId, datePart]);
}

function useDatePart(datePart: SupportedDateParts) {
  const {
    value,
    onChange,
    hasError = false,
  } = useFieldPropsV2<DateInputProps>();
  const { regionalFormat } = useConfig();

  const dateValues = useMemo(() => deserializeDate(value ?? ''), [value]);
  const errors = useMemo(
    () => getDatePartsErrors(hasError, value ?? ''),
    [value, hasError],
  );

  const partValue = dateValues[datePart] || '';

  const onPartChange = useCallback(
    (newValue: string) => {
      const serializedValue = serializeDate(newValue, datePart, dateValues);
      onChange(serializedValue);
    },
    [onChange, dateValues, datePart],
  );

  const isFirstPart = useMemo(() => {
    const dateFormat = getDateFormatParts(regionalFormat)
      .filter(isSupportedDatePart)
      .map((part) => part.toUpperCase() as SupportedDateParts);
    const firstPart = dateFormat[0];
    return firstPart === datePart;
  }, [regionalFormat, datePart]);

  return {
    partValue,
    partError: errors[datePart],
    onPartChange,
    isFirstPart,
  };
}

type DateLabelProps = {
  datePart: SupportedDateParts;
  className?: string;
};

function DateLabel({ datePart, className }: DateLabelProps) {
  const { inputId, labelId } = useDateFieldAttributes(datePart);
  const { t } = useTranslation();

  const translationKey = `field.date.label.${datePart.toLowerCase()}`;
  const label = t(translationKey);

  return (
    <label id={labelId} htmlFor={inputId} className={className}>
      {label}
    </label>
  );
}
