const baseNodeStyle: object = {};

export const NodeStyle = {
  fromJSON(object: any): NodeStyle {
    const message = { ...baseNodeStyle } as NodeStyle;
    message.paddingTop =
      object.paddingTop !== undefined && object.paddingTop !== null
        ? String(object.paddingTop)
        : undefined;
    message.paddingBottom =
      object.paddingBottom !== undefined && object.paddingBottom !== null
        ? String(object.paddingBottom)
        : undefined;
    message.backgroundColor =
      object.backgroundColor !== undefined && object.backgroundColor !== null
        ? String(object.backgroundColor)
        : undefined;
    return message;
  },

  toJSON(message: NodeStyle): unknown {
    const obj: any = {};
    message.paddingTop !== undefined && (obj.paddingTop = message.paddingTop);
    message.paddingBottom !== undefined && (obj.paddingBottom = message.paddingBottom);
    message.backgroundColor !== undefined && (obj.backgroundColor = message.backgroundColor);
    return obj;
  },
};

const baseTextData: object = { text: '' };

export const TextData = {
  fromJSON(object: any): TextData {
    const message = { ...baseTextData } as TextData;
    message.text = object.text !== undefined && object.text !== null ? String(object.text) : '';
    message.decorations = (object.decorations ?? []).map((e: any) => Decoration.fromJSON(e));
    return message;
  },

  toJSON(message: TextData): unknown {
    const obj: any = {};
    message.text !== undefined && (obj.text = message.text);
    if (message.decorations) {
      obj.decorations = message.decorations.map(e => (e ? Decoration.toJSON(e) : undefined));
    } else {
      obj.decorations = [];
    }
    return obj;
  },
};

const baseDecoration: object = { type: Decoration_Type.BOLD };

export const Decoration = {
  fromJSON(object: any): Decoration {
    const message = { ...baseDecoration } as Decoration;
    message.type =
      object.type !== undefined && object.type !== null
        ? decoration_TypeFromJSON(object.type)
        : Decoration_Type.BOLD;
    message.anchorData =
      object.anchorData !== undefined && object.anchorData !== null
        ? AnchorData.fromJSON(object.anchorData)
        : undefined;
    message.colorData =
      object.colorData !== undefined && object.colorData !== null
        ? ColorData.fromJSON(object.colorData)
        : undefined;
    message.linkData =
      object.linkData !== undefined && object.linkData !== null
        ? LinkData.fromJSON(object.linkData)
        : undefined;
    message.mentionData =
      object.mentionData !== undefined && object.mentionData !== null
        ? MentionData.fromJSON(object.mentionData)
        : undefined;
    message.fontSizeData =
      object.fontSizeData !== undefined && object.fontSizeData !== null
        ? FontSizeData.fromJSON(object.fontSizeData)
        : undefined;
    message.fontWeightValue =
      object.fontWeightValue !== undefined && object.fontWeightValue !== null
        ? Number(object.fontWeightValue)
        : undefined;
    message.italicData =
      object.italicData !== undefined && object.italicData !== null
        ? Boolean(object.italicData)
        : undefined;
    message.underlineData =
      object.underlineData !== undefined && object.underlineData !== null
        ? Boolean(object.underlineData)
        : undefined;
    message.spoilerData =
      object.spoilerData !== undefined && object.spoilerData !== null
        ? SpoilerData.fromJSON(object.spoilerData)
        : undefined;
    message.strikethroughData =
      object.strikethroughData !== undefined && object.strikethroughData !== null
        ? Boolean(object.strikethroughData)
        : undefined;
    message.superscriptData =
      object.superscriptData !== undefined && object.superscriptData !== null
        ? Boolean(object.superscriptData)
        : undefined;
    message.subscriptData =
      object.subscriptData !== undefined && object.subscriptData !== null
        ? Boolean(object.subscriptData)
        : undefined;
    message.fontFamilyData =
      object.fontFamilyData !== undefined && object.fontFamilyData !== null
        ? FontFamilyData.fromJSON(object.fontFamilyData)
        : undefined;
    return message;
  },

  toJSON(message: Decoration): unknown {
    const obj: any = {};
    message.type !== undefined && (obj.type = decoration_TypeToJSON(message.type));
    message.anchorData !== undefined &&
      (obj.anchorData = message.anchorData ? AnchorData.toJSON(message.anchorData) : undefined);
    message.colorData !== undefined &&
      (obj.colorData = message.colorData ? ColorData.toJSON(message.colorData) : undefined);
    message.linkData !== undefined &&
      (obj.linkData = message.linkData ? LinkData.toJSON(message.linkData) : undefined);
    message.mentionData !== undefined &&
      (obj.mentionData = message.mentionData ? MentionData.toJSON(message.mentionData) : undefined);
    message.fontSizeData !== undefined &&
      (obj.fontSizeData = message.fontSizeData
        ? FontSizeData.toJSON(message.fontSizeData)
        : undefined);
    message.fontWeightValue !== undefined && (obj.fontWeightValue = message.fontWeightValue);
    message.italicData !== undefined && (obj.italicData = message.italicData);
    message.underlineData !== undefined && (obj.underlineData = message.underlineData);
    message.spoilerData !== undefined &&
      (obj.spoilerData = message.spoilerData ? SpoilerData.toJSON(message.spoilerData) : undefined);
    message.strikethroughData !== undefined && (obj.strikethroughData = message.strikethroughData);
    message.superscriptData !== undefined && (obj.superscriptData = message.superscriptData);
    message.subscriptData !== undefined && (obj.subscriptData = message.subscriptData);
    message.fontFamilyData !== undefined &&
      (obj.fontFamilyData = message.fontFamilyData
        ? FontFamilyData.toJSON(message.fontFamilyData)
        : undefined);
    return obj;
  },
};

const baseMetadata: object = { version: 0 };

export const Metadata = {
  fromJSON(object: any): Metadata {
    const message = { ...baseMetadata } as Metadata;
    message.version =
      object.version !== undefined && object.version !== null ? Number(object.version) : 0;
    message.createdTimestamp =
      object.createdTimestamp !== undefined && object.createdTimestamp !== null
        ? fromJsonTimestamp(object.createdTimestamp)
        : undefined;
    message.updatedTimestamp =
      object.updatedTimestamp !== undefined && object.updatedTimestamp !== null
        ? fromJsonTimestamp(object.updatedTimestamp)
        : undefined;
    message.id = object.id !== undefined && object.id !== null ? String(object.id) : undefined;
    return message;
  },

  toJSON(message: Metadata): unknown {
    const obj: any = {};
    message.version !== undefined && (obj.version = Math.round(message.version));
    message.createdTimestamp !== undefined &&
      (obj.createdTimestamp = message.createdTimestamp.toISOString());
    message.updatedTimestamp !== undefined &&
      (obj.updatedTimestamp = message.updatedTimestamp.toISOString());
    message.id !== undefined && (obj.id = message.id);
    return obj;
  },
};

