import React from 'react';
import { useFieldPropsV2 } from '../../contexts/field-props-context';
import { useConfig } from '../../contexts/config-context';
import { type RichContent } from '@wix/ricos';

interface RichTextProps {
  children: (props: {
    content: RichContent;
    locale: string;
  }) => React.ReactNode;
}

const RichText = ({ children }: RichTextProps) => {
  const { id, FieldLayout, content } = useFieldPropsV2<any>();
  const { locale } = useConfig();

  return (
    <FieldLayout
      fieldId={id}
      renderLabel={() => null}
      renderInput={() => children({ content, locale })}
      renderDescription={() => null}
    />
  );
};

export { RichText };
