import { useState, useEffect } from 'react';
import type { AtlasService } from './atlas-service';
import { generateUUID } from '@wix/form-schema';

type UseAtlasParams = {
  enabled: boolean;
  getInstance: () => string;
  language?: string;
  locale?: string;
  atlasBaseUrl?: string;
};

export const useAtlas = ({
  enabled,
  getInstance,
  language,
  locale,
  atlasBaseUrl,
}: UseAtlasParams) => {
  const [atlas, setAtlas] = useState<AtlasService>();
  const instance = getInstance();
  const [sessionToken, setSessionToken] = useState(generateUUID());
  const refreshSessionToken = () => setSessionToken(generateUUID());

  useEffect(() => {
    if (!enabled) {
      return;
    }

    const initAtlas = async () => {
      try {
        const { createAtlasService } = await import(
          /* webpackChunkName: "atlas-service" */ './atlas-service'
        );
        const atlasService = createAtlasService({
          getInstance: () => instance,
          sessionToken,
          refreshSessionToken,
          language,
          locale,
          atlasBaseUrl,
        });
        setAtlas(atlasService);
      } catch (_error) {}
    };

    initAtlas();
  }, [enabled, instance, language, locale, sessionToken, atlasBaseUrl]);

  return atlas;
};
