import { type ValidationError, groupErrorsByTarget } from '@wix/form-validator';
import { formFieldFocus } from '@wix/bi-logger-forms-platform-uou/v2';
import React, { useCallback, useMemo, useRef } from 'react';
import { useExternalData } from '../../contexts/external-data-context';
import { useFormFields } from '../../contexts/form-fields-context';
import {
  type OnFieldChange,
  type FormValues,
  type InputField as InputFieldEntity,
  type PossibleValues,
} from '../../types';
import { useBi } from '../../../../contexts/bi-context';
import { type FieldLayoutComponent } from '../../../../field-layout';
import { useFieldValidation } from '../../../../contexts/field-validation-context';
import { useForm } from '../../../../contexts/form-context';
import { useError } from '../../../../field-error';
import { FieldPropsContext } from '../../../../contexts/field-props-context';
import {
  FIELD_PROPS_MAPPERS,
  BaseMapper,
} from '../../../../mappers/public-props-map';
import { useFieldAttributes } from '../../../../services/field-attributes';
import { FieldAttributesContext } from '../../../../contexts/field-attributes-context';

export interface InputFieldProps {
  field: InputFieldEntity;
  errors: ValidationError[];
  values: FormValues;
  onFieldChange?: OnFieldChange;
  FieldLayout: FieldLayoutComponent;
}

export const InputField = ({
  field,
  errors,
  values,
  onFieldChange,
  FieldLayout,
}: InputFieldProps) => {
  const bi = useBi();
  const componentsById = useFormFields();
  const externalData = useExternalData();
  const { validateFields } = useFieldValidation();
  const form = useForm();
  const fieldValue = values[field.target];
  const fieldValueRef = useRef(fieldValue);
  fieldValueRef.current = fieldValue;

  const errorsByTarget = useMemo(() => groupErrorsByTarget(errors), [errors]);
  const fieldErrors = errorsByTarget?.[field.target];
  const fieldError = fieldErrors?.[0];
  const { requiredIndicator, requiredIndicatorPlacement } =
    form.requiredIndicatorProperties || {};
  const propsMapper = FIELD_PROPS_MAPPERS[field.fieldType] || BaseMapper;

  const _onBlur = useCallback(() => {
    const currentFieldValue = fieldValueRef.current;
    bi?.report(
      formFieldFocus({
        action_type: 'blur',
        field_id: field.id,
        field_label: field.properties.label,
        field_target: field?.target,
      }),
    );
    validateFields([{ value: currentFieldValue, path: field.path }]);
  }, [
    bi,
    field.id,
    field.properties.label,
    field.target,
    field.path,
    validateFields,
  ]);

  const _onFocus = () => {
    bi?.report(
      formFieldFocus({
        action_type: 'focus',
        field_id: field.id,
        field_label: field.properties.label,
        field_target: field?.target,
      }),
    );
  };

  const handleChange = useCallback(
    (value: PossibleValues) => {
      if (fieldError) {
        validateFields([{ value, path: field.path }]);
      }

      if (
        (!value && value !== 0 && typeof value !== 'boolean') ||
        (Array.isArray(value) && value.length === 0)
      ) {
        value = null;
      }

      onFieldChange?.(field.target, value);
    },
    [onFieldChange, field, fieldError, validateFields],
  );

  const { hasError, errorMessage } = useError({
    error: fieldError,
    customErrors: field.properties?.customErrors,
    fieldType: field.fieldType,
    properties: field.properties,
    validationError: fieldError,
  });

  const FieldComponent = componentsById[field.fieldType];

  const fieldProps = {
    ...field.properties,
    readOnly: Boolean(field.properties?.readOnly),
    onChange: handleChange,
    onBlur: _onBlur,
    onFocus: _onFocus,
    hasError,
    errorMessage,
    error: fieldError,
    errors: fieldErrors,
    value: fieldValue,
    id: field.id,
    target: field.target,
    path: field.path,
    externalData,
    fieldType: field.fieldType,
    FieldLayout,
    requiredIndicatorType: requiredIndicator,
    requiredIndicatorPlacement,
  };

  const fieldAttributes = useFieldAttributes(
    fieldProps.id,
    fieldProps.error,
    fieldProps.description,
  );

  if (!FieldComponent) {
    return null;
  }

  return (
    <FieldAttributesContext.Provider value={fieldAttributes}>
      <FieldPropsContext.Provider
        value={{
          ...propsMapper({
            ...field.properties,
            id: field.id,
            target: field.target,
            path: field.path,
            error: fieldError,
            errors: fieldErrors,
            value: fieldValue,
            externalData,
            fieldType: field.fieldType,
            requiredIndicatorType: requiredIndicator,
            requiredIndicatorPlacement,
          }),
          onChange: handleChange,
          onBlur: _onBlur,
          onFocus: _onFocus,
          hasError,
          errorMessage,
          v2: fieldProps,
        }}
      >
        <FieldComponent {...fieldProps} />
      </FieldPropsContext.Provider>
    </FieldAttributesContext.Provider>
  );
};
